<script setup>
import {ref,watch,onUnmounted,onActivated,onDeactivated} from 'vue';
import DateInput from '../components/DateInput.vue';import BaseModal from '../components/BaseModal.vue';
import {state,company,api,scope,useResource,allowedApi,can,notify,ask,captureContext,contextMatches} from '../lib/workspace';import {uid,money} from '../lib/format';
const props=defineProps({initialSection:{default:'overview'}});const section=ref(props.initialSection),job=ref(null),busy=ref(false),error=ref(''),files=ref([]),start=ref(''),end=ref(''),mode=ref(props.initialSection==='standalone'?'standalone':'internal'),catalogId=ref(''),key=ref(uid()),catalogForm=ref(null),catalogPreview=ref(null),finding=ref(null),findStatus=ref(''),search=ref('');let timer,active=true;
const {data:history,reload}=useResource(()=>allowedApi('auditor.analyses',scope(`/auditor/jobs?year_value=${state.period.slice(0,4)}`)));
const {data:catalogs,reload:reloadCatalogs}=useResource(()=>allowedApi('auditor.catalogs',scope('/auditor/catalogs')));
watch(()=>[state.companyId,state.period.slice(0,4)],()=>{start.value=state.period.slice(0,4)+'-01-01';end.value=state.period.slice(0,4)+'-12-31';job.value=null;files.value=[];key.value=uid();error.value='';clearTimeout(timer)},{immediate:true});
onActivated(()=>{active=true;if(job.value)poll()});onDeactivated(()=>{active=false;clearTimeout(timer)});onUnmounted(()=>{clearTimeout(timer);if(catalogForm.value||finding.value)state.editor=null});
const encode=f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});
async function run(fn){if(busy.value||state.contextBusy)return;const ctx=captureContext(),guard={token:Symbol('operation'),name:'Auditor em processamento'};if(!state.editor)state.editor=guard;busy.value=true;error.value='';try{await fn(ctx)}catch(e){if(contextMatches(ctx))error.value=e.message}finally{busy.value=false;if(state.editor?.token===guard.token)state.editor=null}}
async function load(id){const cid=state.companyId,y=state.period.slice(0,4);const r=await api(scope(`/auditor/jobs/${id}`));if(cid===state.companyId&&y===state.period.slice(0,4)){const finished=['queued','running'].includes(job.value?.status)&&!['queued','running'].includes(r.status);job.value=r;poll();if(finished)await reload()}}
function poll(){clearTimeout(timer);if(active&&['queued','running'].includes(job.value?.status))timer=setTimeout(()=>load(job.value.id).catch(e=>error.value=e.message),1500)}
async function create(){await run(async ctx=>{const params={mode:mode.value,start:start.value,end:end.value,catalog_id:catalogId.value||null,idempotency_key:key.value};let attachments=[];if(mode.value==='standalone'){if(files.value.reduce((s,f)=>s+f.size,0)>20*1024*1024)throw Error('Limite de 20 MiB por lote.');for(const f of files.value)attachments.push({filename:f.name,content_base64:await encode(f)})}const r=await api(scope('/auditor/jobs',ctx.companyId),{method:'POST',context:ctx,body:{...params,files:attachments}});key.value=uid();await reload();await load(r.id);section.value='overview';notify('Auditoria enfileirada. A escrituração será preservada.')})}
async function action(action){const ctx=captureContext(),target={id:job.value.id,version:job.value.version};const reason=await ask({title:action==='delete'?'Excluir auditoria do uso corrente?':'Registrar operação',message:'O histórico e os arquivos serão preservados.',inputLabel:'Justificativa',required:true});if(!reason)return;await run(async()=>{job.value=await api(scope(`/auditor/jobs/${target.id}/${action}`,ctx.companyId),{method:'POST',context:ctx,body:{reason,version:target.version}});poll();await reload()})}
async function generateAux(d){await run(async()=>{await api(scope(`/auditor/jobs/${job.value.id}/auxiliary`),{method:'POST',body:{document_ref:d.document_ref}});await load(job.value.id);notify('DANFE gerado a partir do XML original.');})}
async function reprocess(){await run(async()=>{const r=await api(scope(`/auditor/jobs/${job.value.id}/reprocess`),{method:'POST',body:{idempotency_key:uid(),...(catalogId.value?{catalog_id:catalogId.value}:{})}});await reload();await load(r.id);notify('Nova auditoria criada; resultados anteriores preservados.')})}
function editFinding(f){finding.value={...f};state.editor={name:'Tratamento de achado'}}
function closeEditor(){catalogForm.value=null;finding.value=null;state.editor=null}
async function discard(){if(await ask({title:'Fechar edição?',message:'Os dados ainda não gravados serão descartados.',confirmLabel:'Descartar'}))closeEditor()}
async function saveFinding(){await run(async()=>{await api(scope(`/auditor/findings/${finding.value.id}/treatment`),{method:'PUT',body:finding.value});closeEditor();await load(job.value.id);notify('Tratamento registrado. A origem não foi alterada.')})}
function editCatalog(c=null){catalogPreview.value=null;catalogForm.value=c?{...c,entriesText:JSON.stringify(c.entries,null,2)}:{name:'',source:'',valid_from:start.value,valid_to:end.value,entriesText:'[\n  {"ncm":"", "ex_code":"", "cst":"", "cclass_trib":"", "description":""}\n]'};state.editor={name:'Catálogo do Auditor'}}
async function saveCatalog(){await run(async()=>{const c=catalogForm.value;await api(scope('/auditor/catalogs'+(c.id?'/'+c.id:'')),{method:c.id?'PUT':'POST',body:{...c,acknowledge_issues:!!c.importReviewed,entries:JSON.parse(c.entriesText)}});closeEditor();await reloadCatalogs()})}
async function importCatalog(e){const f=e.target.files[0];if(!f)return;await run(async ctx=>{if(f.size>20*1024*1024)throw Error('Limite de 20 MiB.');const content=await encode(f);const p=await api(scope('/auditor/catalogs/import-preview',ctx.companyId),{method:'POST',context:ctx,body:{filename:f.name,content_base64:content}});if(!catalogForm.value)return;catalogPreview.value=p;catalogForm.value.entriesText=JSON.stringify(p.entries,null,2);catalogForm.value.source_id=p.source_id;catalogForm.value.importReviewed=false;})}
async function publish(c){const ctx=captureContext();const reason=await ask({title:'Publicar catálogo revisado?',message:'Esta versão se tornará imutável. Auditorias anteriores manterão seus catálogos.',inputLabel:'Fonte verificada e conclusão da revisão',required:true});if(!reason)return;await run(async()=>{await api(scope(`/auditor/catalogs/${c.id}/publish`,ctx.companyId),{method:'POST',context:ctx,body:{version:c.version,reason}});await reloadCatalogs()})}
function matches(f){return (!findStatus.value||f.status===findStatus.value)&&JSON.stringify(f).toLocaleLowerCase().includes(search.value.toLocaleLowerCase())}
const labels={overview:'Visão geral',internal:'Auditoria da escrituração',standalone:'Auditoria avulsa',history:'Histórico',findings:'Achados',documents:'Documentos',catalogs:'Catálogos',reports:'Relatórios',logs:'Logs'};
function tab(k){section.value=k;if(['internal','standalone'].includes(k))mode.value=k}
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">AUDITOR FISCAL</div><h1>{{labels[section]}}</h1><p>{{company?.name}} · Exercício {{state.period.slice(0,4)}} · auditoria sem alteração da escrituração</p></div></header>
<div class="section-tabs auditor-tabs"><button v-for="(label,k) in labels" :key="k" v-show="k==='catalogs'?can('auditor.catalogs'):can('auditor.analyses')" :class="{active:section===k}" @click="tab(k)">{{label}}</button></div><p v-if="error" class="message error" role="alert">{{error}}</p>
<section v-if="['internal','standalone'].includes(section)" class="panel"><div class="panel-body"><form @submit.prevent="create"><div class="form-grid three"><label>De<DateInput v-model="start" required/></label><label>Até<DateInput v-model="end" required/></label><label>Catálogo publicado<select v-model="catalogId"><option value="">Sem catálogo — cobertura limitada</option><option v-for="c in catalogs.filter(c=>c.state==='published')" :value="c.id">{{c.name}} · {{c.sha256.slice(0,8)}}</option></select></label></div><label v-if="mode==='standalone'">XML, PDF auxiliar ou ZIP de XML/PDF<input type="file" multiple accept=".xml,.zip,.pdf" @change="files=Array.from($event.target.files)"/></label><p>{{mode==='internal'?'Todos os documentos do intervalo serão fotografados com suas versões e XMLs disponíveis. Competências fechadas podem ser auditadas.':'Arquivos avulsos ficam separados da escrituração. Documentos fora do período são preservados e apontados, mas excluídos dos totais.'}}</p><p>Leitura: NF-e/NFC-e, CT-e/CT-e OS, MDF-e e eventos NF-e. Recálculos tributários somente nos cenários declarados na cobertura. PDF importado não comprova a validade do documento.</p><button class="button primary" v-if="can('auditor.analyses','create')&&(mode==='internal'||can('auditor.analyses','import'))" :disabled="busy">Iniciar auditoria</button></form></div></section>
<section v-else-if="section==='catalogs'" class="panel"><div class="panel-heading"><h2>Versões e publicação</h2><button v-if="can('auditor.catalogs','create')" class="button primary" @click="editCatalog()">Novo catálogo</button></div><p class="panel-body">A publicação registra a revisão do responsável. Não certifica vigência legal e não substitui os parâmetros da escrituração.</p><div class="table-scroll"><table><thead><tr><th>Versão / hash</th><th>Fonte / vigência</th><th>Situação</th><th>Ações</th></tr></thead><tbody><tr v-for="c in catalogs"><td>{{c.name}}<br><code>{{c.sha256.slice(0,16)}}</code></td><td>{{c.source}}<br>{{c.valid_from}} a {{c.valid_to}}</td><td>{{c.state==='draft'?'Rascunho':'Publicado'}} · {{c.entries.length}} regras</td><td><button v-if="c.state==='draft'&&can('auditor.catalogs','edit')" class="text-button" @click="editCatalog(c)">Editar</button><button v-if="c.state==='draft'&&can('auditor.catalogs','book')" class="text-button" @click="publish(c)">Publicar após revisão</button><button v-if="can('auditor.catalogs','create')" class="text-button" @click="editCatalog({...c,id:null,name:c.name+' — revisão'})">Nova versão</button><a v-if="c.source_id&&can('auditor.catalogs','export')" :href="`/api${scope(`/auditor/catalogs/${c.id}/original`)}`">Planilha original</a><details><summary>Regras</summary><pre>{{JSON.stringify(c.entries,null,2)}}</pre></details></td></tr></tbody></table></div></section>
<template v-else><section class="panel"><div class="panel-heading"><h2>Auditorias do exercício</h2><button class="button outline" @click="reload">Atualizar</button></div><div class="table-scroll"><table><thead><tr><th>Auditoria</th><th>Origem / período</th><th>Situação</th><th>Responsável</th><th></th></tr></thead><tbody><tr v-for="h in history" :key="h.id"><td>#{{h.id}}</td><td>{{h.mode==='internal'?'Escrituração':'Avulsa'}} · {{h.start}} a {{h.end}}</td><td>{{h.status}}{{h.deleted_at?' · excluída':''}}</td><td>{{h.created_by}}</td><td><button class="text-button" @click="run(()=>load(h.id))">Abrir</button></td></tr></tbody></table></div></section>
<section v-if="job" class="panel"><div class="panel-heading"><h2>Auditoria #{{job.id}} · {{job.status}}</h2><div class="actions"><button v-if="['queued','running'].includes(job.status)&&can('auditor.analyses','edit')" class="button outline" @click="action('cancel')" :disabled="busy">Cancelar</button><template v-else-if="!['queued','running'].includes(job.status)"><button v-if="can('auditor.analyses','create')" class="button outline" @click="reprocess" :disabled="busy">Reprocessar em novo histórico</button><button v-if="!job.deleted_at&&can('auditor.analyses','delete')" class="button" @click="action('delete')">Excluir logicamente</button><button v-if="job.deleted_at&&can('auditor.analyses','edit')" class="button" @click="action('restore')">Restaurar</button></template></div></div>
<div class="panel-body"><p v-if="job.stale_document_ids.length" class="message warning">A escrituração mudou após esta auditoria: documentos {{job.stale_document_ids.join(', ')}}. Reprocesse para obter um novo retrato.</p><p v-if="job.error" class="message error">{{job.error}}</p><div v-if="section==='overview'||section==='history'"><div class="summary-strip"><div><strong>{{job.result?.totals.documents||0}}</strong><span>documentos na amostra</span></div><div><strong>{{money(job.result?.totals.total_cents||0)}}</strong><span>valor dos documentos</span></div><div><strong>{{job.findings.length}}</strong><span>achados</span></div></div><p>Motor: {{job.snapshot.engine}} · catálogo {{job.snapshot.catalog?.name||'não informado'}}</p><p v-for="limitation in job.coverage.limitations">{{limitation}}</p></div>
<template v-if="section==='findings'"><div class="form-grid"><label>Pesquisar evidência<input v-model="search"/></label><label>Situação<select v-model="findStatus"><option value="">Todas</option><option value="open">Aberto</option><option value="reviewing">Em revisão</option><option value="resolved">Tratado</option><option value="dismissed">Justificado</option></select></label></div><article v-for="f in job.findings.filter(matches)" :key="f.id" class="audit-finding"><strong>{{f.severity}} · {{f.rule_code}} · {{f.title}}</strong><p>{{f.description}}</p><p>Documento {{f.document_ref}} · item {{f.item_number||'—'}} · {{f.status}}</p><details><summary>Evidência e impacto</summary><pre>{{JSON.stringify(f.evidence,null,2)}}</pre><p>{{f.impact}}</p><p>{{f.recommended_action}}</p></details><p>{{f.responsible}} · {{f.treatment}}</p><button v-if="can('auditor.analyses','edit')" class="text-button" @click="editFinding(f)">Registrar tratamento</button></article></template>
<template v-if="section==='documents'"><p>XML original, valores escriturados e memória recalculada permanecem separados.</p><details v-for="d in job.result?.documents" class="audit-finding"><summary>{{d.model}} · {{d.number}} · {{d.total_value}} · {{d.status}} · origem {{d.bookkeeping_id||'avulsa'}}</summary><button v-if="d.model==='55'&&can('auditor.analyses','export')" class="button outline" :disabled="busy" @click="generateAux(d)">Gerar DANFE em Python</button><pre>{{JSON.stringify(d,null,2)}}</pre></details><p v-for="f in job.auxiliary"><a v-if="can('auditor.analyses','export')" :href="`/api${scope(`/auditor/jobs/${job.id}/files?file_id=${f.file_id}`)}`">DANFE gerado · {{f.renderer}}</a></p><h3>Arquivos preservados</h3><p v-for="f in job.snapshot.files"><a v-if="can('auditor.analyses','export')" :href="`/api${scope(`/auditor/jobs/${job.id}/files?file_id=${f.id}`)}`">{{f.name}}</a><span v-else>{{f.name}}</span> · <code>{{f.sha256.slice(0,16)}}</code></p><details><summary>Retrato da escrituração</summary><pre>{{JSON.stringify(job.snapshot.bookkeeping,null,2)}}</pre></details></template>
<template v-if="section==='reports'"><p>Relatórios incluem origens, críticas, evidências, responsáveis, catálogos e memória. Valores decimais originais permanecem explícitos no Excel.</p><div class="actions" v-if="job.status==='completed'"><a v-if="can('auditor.analyses','export')" class="button primary" :href="`/api${scope(`/auditor/jobs/${job.id}/report?format=pdf`)}`">Exportar PDF</a><a v-if="can('auditor.analyses','export')" class="button outline" :href="`/api${scope(`/auditor/jobs/${job.id}/report?format=xlsx`)}`">Exportar Excel</a><a v-if="can('auditor.analyses','print')" class="button outline" target="_blank" :href="`/api${scope(`/auditor/jobs/${job.id}/report?format=pdf&purpose=print`)}`">Visualizar / imprimir PDF</a></div></template>
<template v-if="section==='logs'"><p v-for="(l,n) in job.logs" :key="n"><code>{{l.created_at}}</code> · {{l.level}} · {{l.message}}</p></template></div></section></template>
<BaseModal v-if="finding" title="Tratamento do achado" @close="discard"><form id="finding-form" @submit.prevent="saveFinding"><p>O registro de origem permanecerá inalterado.</p><label>Situação<select v-model="finding.status"><option value="open">Aberto</option><option value="reviewing">Em revisão</option><option value="resolved">Tratado</option><option value="dismissed">Justificado</option></select></label><label>Responsável<input v-model="finding.responsible" required autofocus/></label><label>Tratamento e evidência<textarea v-model="finding.treatment" required rows="5"/></label><p v-if="error" class="message error">{{error}}</p></form><template #footer><button class="button" @click="discard">Fechar</button><button class="button primary" type="submit" form="finding-form" :disabled="busy">Salvar</button></template></BaseModal>
<BaseModal v-if="catalogForm" title="Catálogo do Auditor" wide @close="discard"><form id="catalog-form" @submit.prevent="saveCatalog"><div class="form-grid"><label>Nome da versão<input v-model="catalogForm.name" required autofocus/></label><label>Fonte, edição e revisão normativa<input v-model="catalogForm.source" required/></label><label>Vigência inicial<DateInput v-model="catalogForm.valid_from" required/></label><label>Vigência final<DateInput v-model="catalogForm.valid_to" required/></label></div><label v-if="can('auditor.catalogs','import')">Importar planilha XLSX para conferência<input type="file" accept=".xlsx" :disabled="busy" @change="importCatalog"/></label><div v-if="catalogPreview"><p>{{catalogPreview.rows}} linhas · {{catalogPreview.eligible}} elegíveis · {{catalogPreview.excluded}} excluídas. {{catalogPreview.coverage}}</p><details open><summary>Diagnósticos preservados</summary><p v-for="(i,n) in catalogPreview.issues" :key="n">Linha {{i.source_row}} · {{i.code}} · {{i.message}}</p></details></div><label v-if="catalogForm.source_id" class="check-label"><input type="checkbox" v-model="catalogForm.importReviewed"/>Revisei os diagnósticos, as exclusões e as regras antes de salvar.</label><label>Regras NCM / EX / CST / cClassTrib (JSON)<textarea v-model="catalogForm.entriesText" rows="12" required class="mono"/></label><p>Importe um arquivo JSON de regras:<input type="file" accept=".json" @change="async e=>{const f=e.target.files[0];if(f&&f.size<3000000)catalogForm.entriesText=await f.text()}"/></p><p v-if="error" class="message error">{{error}}</p></form><template #footer><button class="button" @click="discard">Fechar</button><button class="button primary" form="catalog-form" type="submit" :disabled="busy">Salvar rascunho</button></template></BaseModal>
</div></template>
<style scoped>.auditor-tabs{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px}.auditor-tabs button{padding:8px;border:1px solid #ccd5d1;border-radius:6px;background:#f6f8f7;color:#243b34}.auditor-tabs button.active{background:#225f57;color:white}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:420px;overflow:auto;font-size:12px}.audit-finding{padding:14px 0;border-bottom:1px solid #ddd}.panel-body{padding:20px}.actions{flex-wrap:wrap}</style>
